//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Whether this error represents a temporary failure that may be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn only_transient_errors_are_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid input".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between attempts, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `retry_number` failed attempts.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let multiplier = 2u64.checked_pow(retry_number).unwrap_or(u64::MAX);
        self.base_delay_ms
            .saturating_mul(multiplier)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_grows_exponentially_and_saturates() {
        let config = RetryConfig {
            max_attempts: 10,
            base_delay_ms: 25,
            max_delay_ms: 100,
        };

        assert_eq!(config.delay_for_retry(0), 25);
        assert_eq!(config.delay_for_retry(1), 50);
        assert_eq!(config.delay_for_retry(2), 100);
        assert_eq!(config.delay_for_retry(9), 100);
    }

    #[test]
    fn delay_saturates_when_arithmetic_would_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(0), u64::MAX);
        assert_eq!(config.delay_for_retry(1), u64::MAX);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => sleeper.sleep_ms(config.delay_for_retry(attempt - 1)),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_return_without_sleeping() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_limit_includes_first_call_and_delay_is_bounded() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4, 10, 15), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient(format!("failure {calls}")))
        });

        assert_eq!(result, Err(RetryError::Transient("failure 4".into())));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 15, 15]);
    }

    #[test]
    fn zero_attempt_budget_still_makes_one_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(0, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_and_preserves_delays() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 5,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 => Err(RetryError::Transient("temporary outage".into())),
            2 => Err(RetryError::Transient("temporary outage".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![5, 10]);
}

#[test]
fn public_api_returns_permanent_failure_without_retrying() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 5,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert!(sleeper.sleeps.is_empty());
}
